import{SKILLS}from'./expedition-data.mjs';import{SCHEDULE_RULE}from'./expedition-schedule.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function scheduleEvidenceView(event){const w=event?.detail?.schedule;if(!w?.blocked)return '';const o=event.detail.scheduleOutcome,id=o?.eventId,link=Number.isSafeInteger(id)&&id>0,labels={cast:'实际施法',item:'实际自用道具',wait:'实际等待',failed:'普通行动空过'};return `<section class=schedule-proof><h3>回合窗口与实际后备</h3><p>本房第${esc(w.round)}回合，配置窗口${esc(w.from)}–${esc(w.to)}；本条没有施放、不付款、不占行动。后备仍按自己的支付和行动规则执行。</p><p>${o?(link?`${labels[o.type]||'实际后续记录'}${o.skill?'「'+esc(SKILLS[o.skill]?.name||o.skill)+'」':''} · 记录${id}<button data-schedule-outcome="${id}">查看实际后备行动</button>`:o.type==='no-preparation'?'本次没有可执行的预备指令；没有伪造等待或付费。':'没有可定位的后续记录。'):'此记录没有后续证据，不推算执行结果。'}</p><small>${esc(SCHEDULE_RULE)}</small></section>`;}
